INSERT INTO `events` (`id`, `title`, `slug`, `description`, `image`, `venue`, `organizer`, `start_date`, `end_date`, `featured`, `registration_link`, `google_map`, `brochure`, `event_type`, `online_link`, `status`, `created_at`) VALUES
(2, 'PSA WEBINAR SERIES NUMBER 7:  The Politicisation of public appointments and Promotions in Malawi', 'psa-webinar-series-number-7-the-politicisation-of-public-appointments-and-promotions-in-malawi', '<p>The Political Science Association of Malawi (PSA) invites you to the seventh installment of its Webinar Series, focusing on a critical governance challenge: the increasing politicization of public appointments and promotions in Malawi.&nbsp;As concerns over merit, transparency, and institutional integrity continue to grow, this webinar brings together scholars and practitioners to discuss the causes, consequences, and potential reforms related to political interference in the public sector.</p>\r\n\r\n<p><strong>Date:</strong> Monday, 11th May 2026<br />\r\n<strong>Time:</strong> 6:00 PM &ndash; 7:30 PM</p>\r\n\r\n<p><strong>Featured Panelists:</strong></p>\r\n\r\n<p>Dr. Susan Mtuwa &ndash; Keynote Address<br />\r\nBenedicto Kondowe, Chairperson, National Advocacy Platform (NAP) &ndash; Discussant<br />\r\nPeter Chisi, Director of Civil and Political Rights, Malawi Human Rights Commission &ndash; Moderator</p>\r\n\r\n<p>All are welcome to attend. For more information, visit www.malawipsa.org or email admin@malawipsa.org.<br />\r\nFollow us on <strong><a href=\"https://facebook.com/psamalawi\" onclick=\"window.open(this.href, \'PSAFACEBOOKPAGE\', \'resizable=yes,status=no,location=no,toolbar=no,menubar=no,fullscreen=no,scrollbars=no,dependent=no\'); return false;\">FACEBOOK</a></strong>`1&nbsp;for live updates.</p>', '1784278903_1778368907_654251bd.jpg', 'Online', 'Political Science Association', '2026-05-11 18:00:00', '2026-05-11 19:30:00', 0, 'https://teams.live.com/meet/9358183398967?p=Eay0zt9ieBZtMXrR4K', '', 'uploads/events/brochures/1778834838_9614.pdf', 'online', 'https://teams.live.com/meet/9358183398967?p=Eay0zt9ieBZtMXrR4K', 'past', '2026-05-15 08:47:18'),
(3, 'The 4th PSA Biennial Conference — 26th–27th September 2026', 'the-4th-psa-biennial-conference-26th-27th-september-2026', '<p><strong>The Political Science Association of Malawi (PSA) is pleased to announce the 4th PSA Biennial Conference</strong></p>\r\n\r\n<p><br />\r\n<strong>Dates:</strong>&nbsp;26th&ndash;27th September 2026</p>\r\n\r\n<p><strong>Venue:</strong>&nbsp;Sunbird Livingstonia Beach and Waterfront, Salima.</p>\r\n\r\n<p><strong>2026 Theme:</strong> <em>&quot;Malawi&#39;s democracy at the crossroads? Maturing institutions or a tailspin into uncertainty?&quot;</em></p>\r\n\r\n<p><strong>Who Should Attend:&nbsp;</strong>The conference is open to both PSA Members and Non-PSA Members, with options for physical and virtual participation.</p>\r\n\r\n<p><strong>Registration Fees:</strong></p>\r\n\r\n<p><strong><em>Early Bird Fees (Deadline: 1st August 2026)</em></strong></p>\r\n\r\n<ul>\r\n	<li>PSA Members: MK240,000.00 (Physical Participation) | MK140,000.00 (Virtual Participation)</li>\r\n	<li>Non-PSA Members: MK380,000.00 (Physical Participation) | MK280,000.00 (Virtual Participation)</li>\r\n</ul>\r\n\r\n<p><strong><em>Late Fees (Deadline: 18th September 2026)</em></strong></p>\r\n\r\n<ul>\r\n	<li>PSA Members: MK380,000.00 (Physical Participation) | MK280,000.00 (Virtual Participation)</li>\r\n	<li>Non-PSA Members: MK500,000.00 (Physical Participation) | MK400,000.00 (Virtual Participation)</li>\r\n</ul>\r\n\r\n<p><strong>Please note:</strong> registration fees do not include accommodation and transport.</p>\r\n\r\n<p><strong>To register:</strong>&nbsp;contact <a href=\"mailto:admin@malawipsa.org\">admin@malawipsa.org</a>.</p>\r\n\r\n<p>Follow us on Instagram, LinkedIn, X (Twitter), and YouTube: <strong>@malawipsa</strong></p>', '1784278975_1784136183_1246.jpg', 'Sunbird Livingstonia Beach and Waterfront, Salima', 'Political Science Association', '2026-09-26 08:00:00', '2026-09-27 12:00:00', 1, '', '', '', 'physical', '', 'past', '2026-07-15 17:23:03'),
(7, 'Launch of Volume 2, Issue 1 of the Malawi Journal of Politics and Public Affairs', 'launch-of-volume-2-issue-1-of-the-malawi-journal-of-politics-and-public-affairs', '<p>PSA to Host Virtual Launch of Volume 2, Issue 1 of the Malawi Journal of Politics and Public Affairs</p>\r\n\r\n<p>The Political Science Association (PSA), in partnership with the Department of Politics and Government at the University of Malawi, will hold the virtual launch of Volume 2, Issue 1 of the Malawi Journal of Politics and Public Affairs (MJPPA) on Thursday, 20 August 2026, from 6:00 p.m. to 7:30 p.m. Malawi time.</p>\r\n\r\n<p>The launch will feature the journal&rsquo;s Co-Editors-in-Chief, Associate Professor Boniface Dulani and Professor Happy Kayuni. It will provide an opportunity to introduce the new issue, highlight its scholarly contributions, and reflect on the journal&rsquo;s role in promoting research and informed public debate on politics, governance, democracy, and public affairs in Malawi.</p>\r\n\r\n<p>Volume 2, Issue 1 brings together articles examining donor&ndash;government collaboration in Malawi&rsquo;s Social Cash Transfer Programme, political uncertainty during party conventions, decentralisation, councillor turnover and local governance change, and the relationship between universal suffrage and the quality of democracy.</p>\r\n\r\n<p>The event is open to academics, researchers, students, policymakers, governance practitioners, civil-society organisations, the media, and members of the public interested in Malawi&rsquo;s political and governance landscape.</p>\r\n\r\n<p>Event details</p>\r\n\r\n<p>Date: Thursday, 20 August 2026<br />\r\nTime: 6:00 p.m.&ndash;7:30 p.m. Malawi time<br />\r\nVenue: Virtual</p>\r\n\r\n<p>For further information, visit <a href=\"http://www.malawipsa.org/\">www.malawipsa.org</a> or email <a href=\"mailto:admin@malawipsa.org\">admin@malawipsa.org</a>.</p>\r\n\r\n<p>Volume 2, Issue 1, 2026 | ISSN: 3105-224X</p>', '1787048215_IMG-20260818-WA0008.jpg', 'Microsoft Teams App', 'Political Science Association', '2026-08-20 18:00:00', '2026-08-20 19:30:00', 1, '', '', '1787053641_psa223.pdf', 'online', 'https://teams.live.com/meet/9395122851697?p=AlBk4p8TqvCvPlNgxC', 'past', '2026-08-17 20:51:51'),
(9, 'Webinar Series #9', '', '', '1789297923_separation of powers.jpeg', 'Online', 'Political Science Association', '2026-09-17 00:00:00', '2026-08-20 00:00:00', 0, NULL, NULL, NULL, '', NULL, 'upcoming', '2026-09-13 11:12:03');
