INSERT INTO `journals` (`id`, `title`, `volume`, `issue_no`, `journal_date`, `editorial_summary`, `slug`, `file`, `downloads`, `views`, `uploaded_at`, `created_at`, `summary`, `tags`, `pdf`, `author`, `description`) VALUES
(24, 'Malawi Journal of Politics and Public Affairs', '1', '1', '2025-03-01', '', 'malawi-journal-of-politics-and-public-affairs', '', 0, 2, '2026-07-17 18:09:57', '2025-03-01 00:00:00', '', '', NULL, '', NULL),
(28, 'Malawi Journal of Politics and Public Affairs', '2', '1', '2026-08-20', 'OVERVIEW AND AIM OF THE JOURNAL \r\nMalawi Journal of Politics & Public Affairs is an academic journal published by UNIMA Press in partnership with the Political Science Association (PSA) – Malawi. The journal aims to publish and disseminate high-quality articles and research notes on politics and public affairs in Malawi and the world at large and, in the process, promote informed discussions and debates. Ultimately, it is expected that the journal will further assist in the advancement of research, teaching and policy advocacy in Malawi and beyond. The journal is thus an essential and valuable resource for political science and public affairs professionals in private- and public-sector institutions. Except for special issues, the journal will be published biannually in January and December. \r\nThe specific aims of the journal are: \r\n \r\n Generate ideas that can stimulate debate and discussion in the field of political science and public affairs in Malawi and other polities. \r\n Through applied research notes and case studies, contribute to the process of bridging the gap between practitioners and academics in the field of political science and public affairs. \r\n Identify case studies centering on the contemporary challenges and problems faced by public sector institutions and their implications for politics and public affairs in practice. \r\n Provide critical insights into the latest thinking in politics as well as best practices in public affairs. \r\n \r\nSCOPE \r\nThe focus of the journal is primarily on evidence-based articles and research notes that fall within politics and public affairs. Specifically, the scope of the journal includes all sub-fields of political science and public affairs such as (but not limited to): political theory, public administration and management, international relations and development, comparative politics, public policy and law, electoral process and systems and political economy. \r\nREVIEW POLICY AND TYPES OF ARTICLE SUBMISSIONS \r\nMalawi Journal of Politics and Public Affairs operates a double-blind reviewing policy in which the anonymity of authors to reviewers and reviewers to authors will be ensured so as to make the review process fair and just. The Editorial Board welcomes the submission of innovative and contemporary (1) Research Papers, (2) Short Notes or Case Studies and (3) Book Reviews for publication from academics, students and practitioners. \r\n \r\n  EDITORIAL TEAM \r\nThe editorial team is composed of esteemed scholars and practitioners with deep expertise in political science and public affairs. Their collective experience ensures the journal maintains the highest standards of academic rigour and relevance. \r\nChief Editors \r\n Prof. Happy Kayuni, Professor of Political Science, University of Malawi  \r\n Dr. Boniface Dulani, Associate Professor of Political Science, University of Malawi; Director of Surveys at Afrobarometer \r\nEditorial Advisor \r\n Prof. Blessings Chinsinga, Professor of Political Economy, African School of Governance, Rwanda \r\nEditorial Board \r\n Dr. Margaret Sikwese, Novo Habitus Consulting \r\n Prof. Asiyati Chiweza, University of Malawi \r\n Prof. Ragnhild Muriaas, University of Bergen \r\n Dr. Kim Yi Dionne, University of California, Riverside \r\n Dr. Felix Lombe, African Institute of Corporate Citizenship \r\n Dr. Henry Chingaipe, Institute for Policy Research and Social Empowerment \r\n Dr. Toendepi Shonhe, University of South Africa \r\n \r\nEmail:   \r\nmjppa@unima.ac.mw\r\n/admin@malawipsa.org\r\nWebsite:  /', 'malawi-journal-of-politics-and-public-affairs-1', '', 0, 3, '2026-08-20 16:03:09', '2026-08-20 00:00:00', '', 'political theory, public administration and management, international relations and development, comparative politics, public policy and law, electoral process and systems, political economy.', NULL, '', NULL);
