INSERT INTO `journal_topics` (`id`, `journal_id`, `topic`, `article_author`, `article_summary`, `abstract`, `keywords`, `article_date`, `file`, `downloads`, `views`) VALUES
(16, 24, 'Democratization and Anti-Corruption: Lessons from Malawi’s Political Transition', 'Audetter Masaninga', '', 'Despite Malawi’s transition to democracy, corruption remains a significant challenge undermining the country’s political and legal institutions and thereby frustrating meaningful progress. Existing anticorruption strategies have proven insufficient in curbing the vice, prompting the need for innovative approaches. This paper examines how integrating the use of trust law into Malawi’s formal legal framework could provide a more robust approach to combating corruption.\r\nThrough a critical analysis of Malawi’s political and legal history, alongside a review of current anticorruption efforts, the study highlights the limitations of current methods and proposes a novel hybrid framework that incorporates trust law as a complementary mechanism to established legal structures. The findings suggest that this approach could foster a more effective and sustainable fight against corruption.', 'Corruption, Criminal Law, Trust Law', '2025-03-01', 'article_1784312201_03761d4a.pdf', 214, 174),
(17, 24, 'Ideal Deal? — Rethinking The 1954 Anglo-Portuguese Agreement', 'Dan Kuwali', '', 'This paper examines the potential for renegotiation of the 1954 Anglo-Portuguese Agreement (“the Agreement”),\r\nwhich delineated the Mozambique Malawi (then Nyasaland) boundary. The delineation resulted in a significant territorial alteration, granting a net gain of about 6464 square kilometers of land and water surface to the then Portuguese overseas province. Specifically, Article 1(1) of the Agreement shifted the boundary from the eastern shore of Lake Malawi to the median line, annexing almost 6399 square kilometers of water surface to Mozambique. In exchange, Malawi acquired\r\napproximately 20 square kilometers of Portuguese territory in the Angonia area of the Tete District of Mozambique while retaining sovereignty over the Chizumulu and Likoma islands, with all attendant rights. This paper critically examines the geopolitical implications of the arbitrary boundary demarcation outlined in the Agreement, particularly considering the\r\nAfrican Union\'s uti possidetis principle. Such implications extend to sovereignty, security, trade, and regional stability issues. The paper also assesses the underlying rationale behind what appears to be an inequitable agreement on Malawi\'s part by reviewing the Agreement\'s preparatory activities. Furthermore, it investigates potential solutions to this geostrategic quandary and suggests alternatives to address the current challenges. The central thesis is that, when considering the hierarchy of national interests, Lake Malawi may be less important to Mozambique than it is to Malawi. As a result, Malawi could use adept statecraft and diplomatic strategies to persuade Mozambique to renegotiate this\r\ncolonial-era accord, offering a glimmer of hope for a more equitable resolution. In examining the potential for\r\nrenegotiation of the Agreement, the research employed a multifaceted methodology, including a comprehensive\r\nliterature review, legal analysis, and case studies focusing on Malawi and Mozambique. This approach involved document analysis of historical treaties and reports, alongside semi-structured interviews with stakeholders, to gain insights into the geopolitical implications, legal framework, and public sentiment surrounding the Agreement, ultimately aiming to\r\ncontextualise Malawi\'s challenges within broader regional dynamics.', 'Boundary demarcation, Colonial continuities, Regional Stability, Renegotiation, Uti Possidetis', '2025-03-01', 'article_1784313050_b586956d.pdf', 202, 132),
(18, 24, 'Political Party Systems and Their Influence on Policy Horizons in Malawi and Tanzania', 'Clemence Chiposa Alfazema', '', 'Against the claim that democracy influences good policy due to competition, this paper argues that competition in\r\nyoung, fragmented democracies bring insecurity to ruling regimes and this influences the introduction and implementation of short-term policies aimed at getting votes. The argument is in tune with Niles\'s (1999) claim made on social protection programmes that democracies with stable party systems and dominant party systems are likely to choose more progressive policies than nonelected systems and democracies with fragmented party systems. The study utilized a comparative case study approach involving Malawi and Tanzania. Mostly qualitative research design was employed and both primary and secondary data collection methods were utilized supplemented by document analysis and key informant interviews. The data was analysed using content analysis. Findings from the study confirm that\r\nMalawi’s party system is characterized by high fragmentation (substantial number of parties) and low ideological polarization. Higher electoral competition within this fragmented system brings insecurity to the ruling regimes and influences preference for short-term policies aimed at getting votes easily. Party domination in Tanzania, influenced by strong leadership and grounded ideology, has brought security to the ruling regime to formulate and implement policies with longer term horizons and minimal distraction from pluralist forces. Borrowing from Tanzania’s stable policy environment, Malawi’s political system needs to reshape incentives for the institutionalization of political parties. Such incentives would include strengthening the regulation of parties to limit entry and implementation of state funding for parties that obtain a substantive portion of the national vote.', 'Dominant party systems, Fragmented party systems, mandate, ideology, development frameworks, subsidies', '2025-03-01', 'article_1784313763_e9d50e3b.pdf', 201, 106),
(19, 24, 'Political Patronage as a Form of Political Corruption and its Implication for Public Service', 'Bernadette Malunga and Ngcimezile Mweso', '', 'Political patronage is often seen as an impediment to effective governance as it causes economic, political, and social problems. Political patronage is a system of giving individuals or groups appointments, material goods, and favours, among other things. It is used to reward those perceived as supporters or allies and to silence critics. It is founded on the reciprocal relations between patrons and clients. It is often after elections or as a country head into elections that there is an increase in political reward networks around the distribution of public sector jobs and resources. Political patronage may divert public goods from a need-based allocation, pervade public administration (politicisation, not professionalisation of state institutions), severely undermine merit principles and produce a class of elites who control the economic and political powers of the state. The political corruption perpetuated through nepotism and cronyism is about\r\nsecuring voting or rewarding supporters. This paper investigates the use of political patronage in appointments to public service positions, board of directors’ positions, and diplomatic positions as a form of political corruption. The paper argues that official appointments based on actual and perceived political patronage undermine legitimacy, promote public sector\r\ninefficiency and policies for personal gains, and dispossess people of their rights, including equality and non-discrimination. The paper further argues that political patronage hinders the political participation of citizens. The paper recommends several measures to counter political patronage, including the limitation of presidential powers to be replaced by merit-based appointments, the promotion of transparency and accountability of all public officials through, among others, the provision of independent bodies that monitor and question activities of such public officials; the\r\ncapacitation of oversight bodies such as the office of the Ombudsman and the Anti- Corruption Bureau so that they\r\nwork independently without interference from the ruling party. The paper utilises qualitative methods in document analysis to situate political patronage as a concept linked with multiparty democracy where competition among\r\ncandidates increase the likelihood and as argued by others, the necessity of patronage. Using doctrinal research methodology, it also identifies the legal loopholes through which discretion and exercise of power are used to establish patron-based politics. The research also uses secondary data to investigate actual and perceived patron-client relations in the select areas for practice and implications in Malawi.', '', '2025-03-01', 'article_1784314082_06b21ac3.pdf', 203, 138),
(20, 24, 'Political Trust in Malawi Amidst Covid-19 Pandemic', 'Chisomo Magawa', '', 'The COVID-19 pandemic highlighted various social and political issues that affected public trust in state governments. This paper explores political trust in Malawi during the pandemic. The study analyzes public opinion data to assess COVID-19\'s effect on political trust in the country. The findings indicate that the pandemic led to increased distrust in the political system, largely due to misinformation and perceived mishandling of the situation. These factors contributed to a decline in political trust, leaving decision-makers struggling to respond effectively to the pandemic.', 'COVID-19, Political trust, Government, Trust, Malawi', '2025-03-01', 'article_1784314930_9730bd84.pdf', 164, 122),
(27, 28, 'Beyond the Ballot: Universal Suffrage and the Quality of Democracy in the Malawian Context', 'Kondwani Gondwe and Yobe Moyo', '', '', '', '2026-08-20', 'article_1787241789_6ead780f.pdf', 154, 106),
(28, 28, 'When Turnover is Not Enough: Citizen Perspectives on Councillor Replacement and Local Governance Change in Malawi Authors', 'Denis Beneka Mwenda and Mustapha Kennedy Hussein', '', '', '', '2026-08-20', 'article_1787241794_23468376.pdf', 120, 86),
(29, 28, 'Decentralisation in Malawi: Risks and Opportunities', 'Patrick Mogha and Susan Mtuwa', '', '', '', '2026-08-20', 'article_1787241796_d2df2248.pdf', 151, 200),
(30, 28, 'Chaos Quantum Theory as a Metaphor for Political Uncertainty: Insights from Malawian Post-1994 Democratic Party Conventions', 'Mwawi Chirwa and Matthew Phiri', '', '', '', '2026-08-20', 'article_1787241798_8a7294fa.pdf', 108, 90),
(31, 28, 'Beyond the Transaction: The Political Economy of Donor–Government Collaboration in Malawi’s Social Cash Transfer Program', 'Harold S. Kapito and Michael Chasukwa', '', '', '', '2026-08-20', 'article_1787241800_e7e90a76.pdf', 129, 155);
INSERT INTO `news` (`id`, `title`, `slug`, `content`, `summary`, `image`, `author`, `date_posted`, `category`, `tags`, `status`, `created_at`, `featured`, `pdf`, `downloads`) VALUES
(13, '2 years of Tonse Alliance in government Retrospect and Prospects', '2-years-of-tonse-alliance-in-government-retrospect-and-prospects', '<h3>Overview and Aim</h3>\r\n\r\n<p>PSA Newsletter is primarily owned and published by the PSA &ndash; Malawi. The aim of the Newsletter is to publish and disseminate high quality articles (non-academic but grounded on relevant analytical frameworks) on politics and public affairs and in the process promote informed discussions as well as debates. Ultimately it is expected that the newsletter will further assist in advancement of policy advocacy in Malawi and beyond. Thus, the Newsletter is essential as a valuable resource for political science and public affairs professionals in the private and public sector institutions. With the exception of Special editions, the Newsletter will be published biannually in June and December every year.</p>\r\n\r\n<h3>Call for Special Issue</h3>\r\n\r\n<p>The Editors of PSA Newsletter are inviting Articles for a special issue of the Newsletter to be published by early July 2022. This special issue is entitled: &ldquo;A reflection of the State of democracy, governance, and politics in Malawi on the occasion of 2 years of Tonse Alliance in government &ndash; Retrospect and Prospects&rdquo;. Malawi held presidential elections on 23rd June 2020 following the annulment of the May 2019 presidential elections results in which the-then incumbent Peter Mutharika of the Democratic Progressive Party was declared the winner. Opposition leader Lazarus Chakwera of the Malawi Congress Party (but heading the electoral Tonse Alliance composed of 9 parties including the MCP, UTM, AFORD, PPM, Umodzi Party, MAFUNDE, Peoples Party, PETRA, and Freedom Party) emerged victorious in this Presential lections re-run when he got 59% of the votes. Chakwera was eventually sworn-in as President of Malawi on 28th June 2022. This presidential re-run was therefore very unique for many reasons which include: The court verdict that led to these elections set a milestone across African politics, for it made Malawi just the second country south of the Sahara to have presidential poll results annulled by the courts (after Kenya in 2017). But unlike the Kenyan case, the presidential re-run was won by an opposition leader. The said court ruling also had a significant impact on the Malawi presidential electoral system. Specifically, through the court&rsquo;s interpretation of the Malawi constitution, June 2020 presidential elections witnessed the 50%+1 rule being applied for the first time. Another unique element was persistent and well-coordinated protests, against the May 2019 presidential elections results, with the army playing a key role to protect the protesters when the police failed to manage the situation. Equally important was the fact that the ushering of the new Tonse Alliance government provided a new wave of hope that the new regime would translate the campaign rhetoric of championing a transformational leadership in order to &ldquo;clear the rubble&rdquo; and &ldquo;broken system&rdquo;. On 28th June 2022, the Tonse Alliance government will have clocked exactly 2 years in office.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Purpose</h3>\r\n\r\n<p>To critically reflect on the state of democracy, governance, and politics in Malawi within 2 years of Tonse Alliance at the helm. What are the gains, losses, lessons and implications on politics, governance, and public affairs? What are the retrospects and prospects? Ultimately it is expected that the articles submitted will provide further insights into the implications of this state of democracy, governance, and politics for the past 2 years not only in Malawi but also in Africa and beyond. This Special edition will also highlight the recent achievements of individual members of the Association. The Newsletter will be published on the PSA website.On ly members of PSA will be eligible to submit articles to be considered for publishment under this Issue. Interested members are advised to contribute to any of the following sub-themes:</p>\r\n\r\n<ul>\r\n	<li>Civil Society, civic space, NGO Accountability and human rights</li>\r\n	<li>Coalition politics and governance &amp; Intraparty politics and democracy.</li>\r\n	<li>Covid-19, politics and democracy and Political leadership, governance and democracy</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>National politics and chieftaincy: Relationship between the state, the ruling party on one hand and chiefs</li>\r\n	<li>The Opposition and democracy &amp; Parliament and democracy &amp; Public sector reforms, democracy and governance</li>\r\n	<li>Peace and security OR Corruption, OR Campaign promises Versus Action OR Gender, governance and politics. &amp; Elections, politics and governance.</li>\r\n	<li>Establish and foster closer relationship between political scientists and government officials, academic institutions, Civil Society, and the Media.</li>\r\n	<li>Promote the study, research and publications related to but not limited to Malawi politics.</li>\r\n	<li>Promote activities of associations of Political Science students in education institutions in Malawi.Members of Parliament &amp; Candidates</li>\r\n</ul>\r\n\r\n<h3>Specifications</h3>\r\n\r\n<p>The articles should be within the word range of 700 to 1000 words. The articles must be analytical and must set out a brief analytical framework and proceed to deal with the issue. The deadline for submission of Articles is 30th June 2022, 12:00 midnight. All the articles will be published on this site and should be submitted to the following</p>\r\n\r\n<p><br />\r\n&nbsp;snkowani@gmail.com&nbsp; | raphaelfeiva@gmail.com.</p>\r\n', NULL, 'uploads/news/2026/04/1776407855_56de354d.jpg', 'Len', '2022-06-27', 'Politics', 'Politics, Elections, Tonse Alliance', 'published', '2026-04-17 06:37:36', 0, NULL, 0),
(11, 'Call for abstracts book title: The Malawi 2025 General Elections: New Laws and Systems, better outcomes?', 'call-for-abstracts-book-title-the-malawi-2025-general-elections-new-laws-and-systems-better-outcomes', '<h3>Introduction</h3>\r\n\r\n<p>The editors of the book, Associate Professor Nandini Patel, Professor Happy Kayuni and Dr. Henry Chingaipe, invite scholars, researchers, and practitioners to submit abstracts for consideration for inclusion in the forthcoming publication titled: &ldquo;The Malawi 2025 General Elections: New Laws and Systems, Better Outcomes?&rdquo; by the National Initiative for Civic Education (NICE), the Institute for Policy Interaction (IPI), and the Political Science Association (PSA).</p>\r\n\r\n<h3>Scope</h3>\r\n\r\n<p>The Political Science Association of Malawi will hold its 3rd Biennial Conference from 3-4 May, 2025-2026 at Sunbird Nkopola Lodge in Mangochi under the theme: &#39;3oth Anniversary of Multiparty Democracy: Reflections on Malawi&#39;s Governance, Politics and Development&#39;. This is a Premium gathering of Local and International Political Scientists. For Details on how to be part of this gathering, email PSA Admin:&nbsp;<strong>admin@psamalawi.org</strong>.</p>\r\n\r\n<h3>Objectives</h3>\r\n\r\n<p>The proposed book shall adopt a wide-ranging and systematic approach. Embracing an electoral cycle framework approach and utilising the &quot;electoral governance&quot; lens, the volume is intended to go beyond superficial documentation of experiences to present candid analyses of the performance and viability of institutional arrangements, structural dynamics, and human agency to shed light on how, singularly or jointly, they impact the quality of democracy generally, and electoral democracy in particular. Thus, by covering the complete electoral cycle&mdash;from pre-election preparations to post-election dispute resolution&mdash;the proposed book envisages a holistic investigation that emphasizes achievements, vulnerabilities and resilience factors of Malawi&rsquo;s electoral democracy.</p>\r\n\r\n<ul>\r\n	<li>To evaluate the implementation of the 2020 electoral reforms and their impact on the 2025 general elections.</li>\r\n	<li>To assess the implementation of the Political Parties Act, particularly the regulation of campaign hand-outs, in promoting fair competition and transparency on expenditures through party disclosures;</li>\r\n	<li>To assess whether and how the media, both conventional and modern, impact the political participation of various segments of the electorate and competition among candidates and political parties;</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>To assess the status of inclusivity of the electoral process, especially for women, youth and differently-abled persons;</li>\r\n	<li>To examine the role of technology in elections, including the politics of adoption and uptake, contributions to efficiency and effectiveness in - The management of elections and the associated risks and challenges of technology;</li>\r\n	<li>To identify and analyse the drivers of electoral violence and assess the effectiveness of the institutional framework for resolving electoral disputes and preventing and penalising electoral violence;</li>\r\n	<li>To evaluate the delivery and impact of Civic and Voter Education (CVE);</li>\r\n	<li>To compile information and reflect on election observations; and To compare Malawi&rsquo;s electoral challenges and successes with regional and international trends to draw broader insights.</li>\r\n</ul>\r\n\r\n<h3>Themes</h3>\r\n\r\n<ul>\r\n	<li>The Legal Framework, the Electoral Reforms and Implementation</li>\r\n	<li>Boundary Re-demarcation of Constituencies and Wards</li>\r\n	<li>Technology in Elections</li>\r\n	<li>Inclusivity and Participation: Progress and Challenges for Women and Youth and Differently-abled Persons</li>\r\n	<li>The Management of the 2025 Elections</li>\r\n	<li>Political Parties &ndash; Conventions, Primaries, Campaign</li>\r\n	<li>Media &ndash; Mainstream and Digital</li>\r\n	<li>Civil Society &ndash; Civic education, Voter Mobilisation and Election Observation</li>\r\n	<li>Analysing the Vote</li>\r\n	<li>Electoral Disputes, Violence, Resolution and Election Observation</li>\r\n</ul>\r\n\r\n<p><strong>Guidelines</strong></p>\r\n\r\n<ul>\r\n	<li>Word limit: 300 words</li>\r\n</ul>\r\n\r\n<p><strong>Submission deadline</strong></p>\r\n\r\n<ul>\r\n	<li>6th March 2025. Late submissions will not be considered.</li>\r\n	<li>Submissions to: malawi.ipi@outlook.com and copied to admin@malawipsa.org.</li>\r\n</ul>\r\n\r\n<div style=\"background:#eeeeee; border:1px solid #cccccc; padding:5px 10px\"><strong>We eagerly look forward to your submissions.</strong></div>\r\n', NULL, 'uploads/news/2026/04/1776406355_5176576f.jpg', 'Len', '2025-02-20', 'Abstracts', 'General Elections, Laws, 2025', 'published', '2026-04-17 06:12:35', 1, 'uploads/pdfs/1776410135_8a439373.pdf', 0),
(12, '3rd Biennial PSA Conference and Call for Papers THEME: 30 Years of Multiparty Democracy', '3rd-biennial-psa-conference-and-call-for-papers-theme-30-years-of-multiparty-democracy', '<h3>Background and Purpose of the Conference/ Special Issue Journal</h3>\r\n\r\n<p>The Political Science Association (PSA) is a registered entity with a diverse membership of academics and professionals in the fields of political science, political philosophy, political and economic governance, public administration, international relations, public law, public policy and political economy analysis and other related disciplines relevant to the study, analysis and understanding of politics. The purpose of PSA is to contribute to political and socio-economic development of Malawi through promoting the study and analysis of politics through research, advocacy and policy dialogue.<br />\r\n<br />\r\nThe Political Science Association (Malawi), in collaboration with the editors of Malawi Journal of Politics &amp; Public Affairs and the University of Malawi&rsquo;s Department of Politics and Government, are pleased to announce its 3rd Biennial Conference, scheduled to take place from the 25th to the 27th of April 2025-2026. The theme of the conference is &ldquo;30 Years of Multiparty Democracy: Reflections on Malawi&rsquo;s Governance, Politics, and Development&rdquo;. This conference holds special significance as it marks 30 years since Malawi transitioned from a one-party system to a multiparty democracy in 1994. In light of this important political milestone, the conference aims to serve as a platform for stakeholders to undertake a comparative analysis and a critical examination of the first 30 years of one-party rule (1964-1994) and the subsequent multi-party era (1994-2025-2026). Specifically, the2 overall objective is to gain insights into the political, social, and economic transformations that Malawi has experienced, hence drawing lessons for the future.<br />\r\n<br />\r\nThe 3rd Biennial conference will therefore provide a platform for academics, researchers, policymakers, and practitioners to engage in deep discussions, share perspectives, and present empirical findings related to Malawi&#39;s political landscape over the two distinctive periods. In conjunction with the conference, the Political Science Association is calling for the submission of papers for presentation at the conference, which will be considered for publication in a special issue of the Malawi Journal of Politics and Public Affairs.</p>\r\n\r\n<h3>Specific Thematic Areas</h3>\r\n\r\n<p>The Political Science Association of Malawi will hold its 3rd Biennial Conference from 3-4 May, 2025-2026 at Sunbird Nkopola Lodge in Mangochi under the theme: &#39;3oth Anniversary of Multiparty Democracy: Reflections on Malawi&#39;s Governance, Politics and Development&#39;. This is a Premium gathering of Local and International Political Scientists. For Details on how to be part of this gathering, email PSA Admin:&nbsp;<strong>admin@psamalawi.org</strong>.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Purpose</h3>\r\n\r\n<p>Papers are invited on the following thematic areas, with a focus on the comparative analysis between the first 30 years of one-party rule and the subsequent multi-party era:</p>\r\n\r\n<ul>\r\n	<li>Governance Structures and Political Evolution- Comparing the governance structures and political dynamics during the one-party era and the multi-party democracy.</li>\r\n	<li>Party Politics and Institutional Framework- Analyzing the evolution of political parties, their roles, and the impact of the institutional framework on political stability.</li>\r\n	<li>Socioeconomic Development- Assessing the impact of political systems on socioeconomic development during both periods, including issues of poverty reduction, education, healthcare, and infrastructure.</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>Citizen Participation and Political Culture- Investigating changes in political culture and the extent of citizen participation in the democratic process across the two eras.</li>\r\n	<li>Foreign Policy and Diplomacy- Comparing the foreign policy approaches, regional integration relationships, and international standing during the one-party rule and multiparty democracy.</li>\r\n	<li>Media&#39;s Role in Politics - exploring the role of media in shaping political processes during the two distinctive periods.</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Civil Society Dynamics- Examining the evolution and impact of civil society in promoting political accountability, inclusivity, and social justice.</li>\r\n	<li>Anti-Corruption Strategies and Public Sector Reforms- Assessing the effectiveness of anticorruption strategies and public sector reforms in enhancing transparency, accountability, and efficiency in governance.</li>\r\n</ul>\r\n\r\n<h3>Timelines</h3>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Abstract Submission Deadline: 18th March 2025-2026</li>\r\n	<li>Notification of Acceptance: 1 April 2025-2026</li>\r\n	<li>Presentation of Selected Papers: 3rd Biennial PSA Conference, 3rd- 4th May 2025-2026</li>\r\n	<li>Full Paper Submission Deadline: 17th May 2025-2026</li>\r\n	<li>Publication: July - August 2025-2026</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>We invite interested scholars and researchers to submit abstracts addressing the conference theme, with a specific focus on the comparative analysis of the two distinctive periods in Malawi&#39;s political history. Abstracts should be sent to&nbsp;&nbsp;hkayuni@unima.ac.mw&nbsp;&nbsp;bdulani@unima.ac.mw by the submission deadline. Selected papers presented during the conference will be considered for publication in the July 2025-2026 issue of the Malawi Journal of Politics &amp; Public Affairs.<br />\r\n<br />\r\n<strong>For further details please download the concept note</strong></p>\r\n', NULL, 'uploads/news/2026/04/1776407354_0c487a84.jpg', 'Len', '2025-02-15', 'Conference', ' Politics, Economics, Foreign Policy', 'published', '2026-04-17 06:29:14', 1, NULL, 0),
(14, 'Call for Papers- the 4th Biennial Conference for Malawi Political Science Association (PSA)', 'call-for-papers--the-4th-biennial-conference-for-malawi-political-science-association-psa', '<p><strong>Political Science Association Announces 4th Biennial Conference Call for Papers</strong></p>\r\n\r\n<p>The Political Science Association (PSA) of Malawi has officially announced a Call for Papers for its upcoming <strong>4th Biennial Conference</strong>, scheduled to take place from <strong>8th to 9th August 2026</strong> at the <strong>Sunbird Livingstonia Beach and Waterfront in Salima</strong>.</p>\r\n\r\n<p>The conference will be held under the theme:<br />\r\n<em>&ldquo;Malawi&rsquo;s democracy at the crossroads? Maturing Institutions or a Tailspin into Uncertainty?&rdquo;</em>&mdash;a timely and thought-provoking topic that seeks to examine the current state, resilience, and future trajectory of Malawi&rsquo;s democratic governance.</p>\r\n\r\n<p>Established under the Trustees Incorporation Act, the PSA is a professional body bringing together academics and practitioners from fields such as political science, governance, public administration, international relations, public policy, and political economy. The association plays a vital role in promoting research, policy dialogue, and critical analysis to support Malawi&rsquo;s political and socio-economic development.</p>\r\n\r\n<p>This year&rsquo;s conference holds special significance as it marks <strong>15 years since the establishment of PSA</strong>, and comes more than three decades after Malawi&rsquo;s transition to multiparty democracy in 1993. It also follows the <strong>2025 general elections</strong>, which ushered in a new administration and sparked renewed debate on the strength, performance, and independence of democratic institutions.</p>\r\n\r\n<p>The conference will provide a platform for <strong>academics, researchers, policymakers, practitioners, and citizens</strong> to engage in meaningful discussions and share insights on Malawi&rsquo;s evolving political landscape. Key thematic areas include elections and democratic consolidation, governance and institutions, political parties, citizen participation, media and civil society, as well as emerging challenges such as digital influence, climate governance, and security.</p>\r\n\r\n<p>The PSA is inviting <strong>abstract submissions (maximum 300 words)</strong> that clearly outline the research question, methodology, and key arguments. Accepted papers will be presented during the conference and may be considered for publication in the <strong>Malawi Journal of Politics and Public Affairs (MJPPA)</strong> following a rigorous peer-review process.</p>\r\n\r\n<h3><strong>Key Dates</strong></h3>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Abstract Submission Deadline:</strong> 30 April 2026</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Notification of Acceptance:</strong> 20 May 2026</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Full Paper Submission:</strong> 20 July 2026</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Conference Dates:</strong> 8&ndash;9 August 2026</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3><strong>Submission &amp; Enquiries</strong></h3>\r\n\r\n<p>All abstracts should be sent via email to:<br />\r\n📧 <strong><a href=\"mailto:malawipsa@gmail.com\">malawipsa@gmail.com</a></strong><br />\r\n📧 <strong><a href=\"mailto:hkayuni@unima.ac.mw\">hkayuni@unima.ac.mw</a></strong><br />\r\n📧 <strong><a href=\"mailto:bdulani@unima.ac.mw\">bdulani@unima.ac.mw</a></strong></p>\r\n\r\n<p>Researchers and interested participants are encouraged to submit their work early and be part of this important academic and policy dialogue shaping Malawi&rsquo;s democratic future.</p>\r\n\r\n<hr />\r\n<h3>📄 <strong>Full Conference Guidelines</strong></h3>\r\n\r\n<p>For detailed submission requirements, formatting guidelines, and full conference information, <strong>please download the full Call for Papers document using the button below</strong>.</p>\r\n', NULL, 'uploads/news/2026/04/1776433169_8388ad8f.jpg', 'Admin', '2026-04-17', 'Conference', 'Malawi, Political Science,  Africa, Academic Conference, PSA Malawi, Malaw', 'published', '2026-04-17 13:39:29', 1, 'uploads/pdfs/1776433169_a1740dc8.pdf', 0),
(25, 'Webinar 7 | The Politicization of Public Appointments and Promotions in Malawi (Insights from PhD Thesis)', 'webinar-7-the-politicization-of-public-appointments-and-promotions-in-malawi-insights-from-phd-thesis', '<p>The Political Science Association of Malawi (PSA) invites you to the seventh installment of its Webinar Series, focusing on a critical governance challenge: the increasing politicization of public appointments and promotions in Malawi.&nbsp;As concerns over merit, transparency, and institutional integrity continue to grow, this webinar brings together scholars and practitioners to discuss the causes, consequences, and potential reforms related to political interference in the public sector.</p>\r\n\r\n<p>Date: Monday, 11th May 2026<br />\r\nTime: 6:00 PM &ndash; 7:30 PM<br />\r\nPlatform: Microsoft Teams (scan the QR code to join) | Live on Facebook at fb.com/psamw<br />\r\nFeatured Panelists:</p>\r\n\r\n<p>Dr. Susan Mtuwa &ndash; Keynote Address<br />\r\nBenedicto Kondowe, Chairperson, National Advocacy Platform (NAP) &ndash; Discussant<br />\r\nPeter Chisi, Director of Civil and Political Rights, Malawi Human Rights Commission &ndash; Moderator</p>\r\n\r\n<p>All are welcome to attend. For more information, visit www.malawipsa.org or email admin@malawipsa.org.<br />\r\nFollow us on FACEBOOK`1&nbsp;for live updates.</p>', '', '1784279753_1778834838_6351.jpeg', '$Admin', '2026-05-10', 'Webinar Series', '', 'published', '2026-05-10 04:38:30', 1, 'uploads/pdfs/1778387910_dc305a16.pdf', 0),
(28, 'Publication Alert: Malawi Journal of Politics and Public Affairs First Issue', 'publication-alert-malawi-journal-of-politics-and-public-affairs-first-issue', '<p>First Issue of the Malawi Journal of Politics and Public Affairs Now Available</p>\r\n\r\n<p>The Co-Editors-in-Chief of the Malawi Journal of Politics and Public Affairs (MJPPA), in collaboration with the Executive Council of the Political Science Association (Malawi) and the Politics and Government Department of the University of Malawi (UNIMA), are pleased to announce the online publication of the first issue of MJPPA.</p>\r\n\r\n<p>The journal provides a platform for rigorous scholarship and timely discussion on politics, governance and public affairs in Malawi and beyond. This inaugural issue features the following articles:</p>\r\n\r\n<p>- Democratization and Anti-Corruption: Lessons from Malawi&#39;s Political Transition<br />\r\n- Ideal Deal? - Rethinking the 1954 Anglo-Portuguese Agreement<br />\r\n- Political Party Systems and Their Influence on Policy Horizons in Malawi and Tanzania<br />\r\n- Political Patronage as a Form of Political Corruption and its Implication for Public Service<br />\r\n- Political Trust in Malawi Amidst COVID-19 Pandemic</p>\r\n\r\n<p>Read, view or download the issue at: https://malawipsa.org/journal&nbsp;</p>\r\n\r\n<p>The Second Issue will be launched during the 4th Biennial Conference in September 2026 and made available on UNIMA and PSA Websites.</p>', '', '1784674311_MJPPA_First_Issue_Conference_Style_Flyer_v2.png', 'Admin', '2026-07-21', 'Journal Publication Alert', '', 'published', '2026-07-21 22:51:51', 1, '', 0),
(29, 'PSA 4th Biennial Conference - Registration Closes 18 September 2026', 'psa-4th-biennial-conference---registration-closes-18-september-2026', '<h3><strong>Theme:</strong> Malawi&#39;s Democracy at the Crossroads? Maturing Institutions or a Tailspin into Uncertainty?</h3>\r\n\r\n<p><strong>Dates:</strong> 26th&ndash;27th September 2026<br />\r\n<strong>Venue:</strong> Sunbird Livingstonia Beach and Waterfront, Salima</p>\r\n\r\n<p>With the registration deadline two weeks away, PSA members and non-members alike are invited to join this year&#39;s conference for a critical examination of Malawi&#39;s democratic trajectory.</p>\r\n\r\n<p><strong>Programme highlights</strong></p>\r\n\r\n<ul>\r\n	<li>Keynote speech</li>\r\n	<li>Panel discussions</li>\r\n	<li>Capacity building session</li>\r\n	<li>Presentation and discussion of accepted conference papers</li>\r\n	<li>Cocktail and award presentation</li>\r\n	<li>Annual General Meeting (AGM)</li>\r\n</ul>\r\n\r\n<p><strong>Registration fees</strong></p>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th scope=\"col\">Category</th>\r\n			<th scope=\"col\">Physical</th>\r\n			<th scope=\"col\">Virtual</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>PSA Members</td>\r\n			<td>MK380,000</td>\r\n			<td>MK280,000</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Non-PSA Members</td>\r\n			<td>MK500,000</td>\r\n			<td>MK400,000</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><em>Fees exclude accommodation and transport.</em></p>\r\n\r\n<p><strong>How to register</strong> Contact the PSA Secretariat at <a href=\"mailto:admin@malawipsa.org\">admin@malawipsa.org</a> before the registration deadline of 18th September 2026.</p>', '', '1788511868_conferene flyer.jpeg', 'PSA Admin', '2026-09-04', 'Conference', '', 'published', '2026-09-04 08:51:08', 1, '', 0),
(30, 'Webinar |9: Separation of Powers, Checks and Balances in Democratic Malawi.', 'webinar-9-separation-of-powers-checks-and-balances-in-democratic-malawi', '<p><strong>Parliament, the Judiciary and the Executive: Where Does Each Arm&rsquo;s Power Begin and End?</strong></p>\r\n\r\n<p>The Malawi Political Science Association (PSA) invites you to Webinar Series #9: <strong>&ldquo;Separation of Powers, Checks and Balances in Democratic Malawi.&rdquo;</strong></p>\r\n\r\n<p>At a time when developments in Malawi are prompting questions about the exercise of public power, understanding the roles and limits of Parliament, the Judiciary and the Executive is essential. Who has the authority to do what? How should these institutions hold one another accountable? And when does the exercise of oversight become interference?</p>\r\n\r\n<p>This timely discussion will examine the relationships between the three arms of government and what they mean for constitutional democracy, accountable leadership and citizens&rsquo; rights.</p>\r\n\r\n<p>The principal speaker, <strong>Associate Professor Nandini Patel</strong>, Executive Director of the Institute for Policy Interaction, brings extensive scholarship on Malawi&rsquo;s politics and democratic institutions. She co-edited the book of&nbsp;<em>Government and Politics in Malawi</em> and co-authored a chapter in this book on the legislature - experience directly relevant to understanding Parliament&rsquo;s place in the country&rsquo;s democracy.</p>\r\n\r\n<p><strong>Associate Professor Garton Kamchedzera</strong>, Associate Professor of Law at the University of Malawi, will serve as discussant. A Cambridge-trained legal scholar whose work addresses human rights, constitutional governance and the performance of legislative duties, he brings a valuable legal perspective on the responsibilities and limits of state institutions.</p>\r\n\r\n<p>The session will be moderated by <strong>Dr Michael Jana</strong>, Executive Council Member of the Political Science Association.</p>\r\n\r\n<p>Questions at the heart of the discussion include:</p>\r\n\r\n<ul>\r\n	<li>Where do the mandates of Parliament, the Judiciary and the Executive begin and end?</li>\r\n	<li>How should checks and balances work in practice?</li>\r\n	<li>How can institutions exercise oversight while respecting one another&rsquo;s independence?</li>\r\n	<li>What does separation of powers mean for citizens and democratic accountability?</li>\r\n</ul>\r\n\r\n<p><strong>Date:</strong> Thursday, 17 September 2026<br />\r\n<strong>Time:</strong> 18:00&ndash;19:30 Malawi time (CAT/SAST; UTC+2)<br />\r\n<strong>Platform:</strong> Microsoft Teams<br />\r\n<strong>To join:</strong> Scan the QR code on the accompanying event poster.</p>\r\n\r\n<p>We invite citizens, students, academics, legal practitioners, policymakers, civil society organisations and the media to join this important conversation.</p>\r\n\r\n<p><strong>Join us as we examine who exercises power, who checks it, and how Malawi&rsquo;s democracy can make accountability work.</strong></p>', '', '1789289163_separation of powers.jpeg', 'Admin', '2026-09-13', 'Webinar Series', '', 'published', '2026-09-13 08:46:03', 0, '1789289163_psa Webinar Series#9.pdf', 0),
(31, 'Introducing Session 2 of the PSA 4th Biennial Conference: Regional and comparative perspectives; and political parties and representation', 'introducing-session-2-of-the-psa-4th-biennial-conference-regional-and-comparative-perspectives-and-political-parties-and-representation', '<p>Session 2 of the PSA 4th Biennial Conference turns to <em>Regional and comparative perspectives; and political parties and representation</em>.<br />\r\n<br />\r\nThe session is chaired by Prof. Happy Kayuni (Co-Editor-in-Chief, MJPPA; Executive Dean, SLEG, University of Malawi), with contributions from<br />\r\n1.&nbsp;Dr. Eugenio Njoloma and Juliana Lunguzi,<br />\r\n2.&nbsp;Prof. Michael Chasukwa and Blessings Mbendera,<br />\r\n3.&nbsp;Chimwemwe Kandodo, Sainala Kalebe, Beauty Phiri, et al<br />\r\n4.&nbsp;and Dr. Tiyesere Chikapa.<br />\r\n<br />\r\nJoin us on 26th September at Sunbird Livingstonia Beach &amp; Water Front, Salima.</p>', '', '1790067171_Session 2.jpeg', 'Admin', '2026-09-22', 'Conference', '', 'published', '2026-09-22 08:52:51', 0, '', 0),
(32, 'PSA 4th Biennial Conference Session 5: Governance and Institutions', 'psa-4th-biennial-conference-session-5-governance-and-institutions', '', '<p>Session 5 of the PSA 4th Biennial Conference addresses <em>Governance and Institutions</em>, chaired by Dr. Kizito Tenthani, Registrar of Political Parties in Malawi.<br />\r\n<br />\r\nAuthors presenting in this session include</p>\r\n\r\n<p>1. Richard Wasili James and Dr. Susan Mtuwa,<br />\r\n2.&nbsp;Raphael Nedi,<br />\r\n3.&nbsp;Chimwemwe Salie Hara, and<br />\r\n4.&nbsp;Dr. Chrispine Mphande.<br />\r\n<br />\r\nJoin us on 26th September at Sunbird Livingstonia Beach &amp; Water Front, Salima.</p>', '1790199497_Session 5.jpeg', '', '2026-09-23', '', '', 'published', '2026-09-23 21:38:17', 0, '', 0),
(33, 'PSA 4th Biennial Conference Session 4: Elections and Democratic Consolidation', 'psa-4th-biennial-conference-session-4-elections-and-democratic-consolidation', '<p><br />\r\nPSA 4th Biennial Conference lineup.<br />\r\n<br />\r\nSession 4:&nbsp;<em>Elections and Democratic Consolidation,&nbsp;</em>is chaired by Samantha Mosiwa (Senior Lecturer in Political Science, University of Malawi), with authors</p>\r\n\r\n<p>1. Audetter Masaninga,<br />\r\n2. Wellington Katantha,<br />\r\n3. Luke Nkhoma and<br />\r\n4.&nbsp;Samuel Iwalani.</p>\r\n\r\n<p>Join us on 26th September at Sunbird Livingstonia Beach &amp; Water Front, Salima.</p>', '', '1790278125_Session 4.jpeg', '', '2026-09-24', '', '', 'published', '2026-09-24 19:28:45', 0, '', 0),
(34, 'Session 6: Citizenship, Civil Society and Public Opinion', 'session-6-citizenship-civil-society-and-public-opinion', '<p>Session 6:&nbsp;<em>Citizenship, Civil Society and Public Opinion,&nbsp;</em>&nbsp;is chaired by Prof. Mustafa Hussein (Professor of Public Administration, University of Malawi), featuring<br />\r\n1.&nbsp;Dr. Llyod George Banda,<br />\r\n2.&nbsp;Tapiwa Ngwembe and Dr. Felix Lombe,<br />\r\n3.&nbsp;Nadia Notiyhella Nathoo and<br />\r\n4.&nbsp;Kondwani Gondwe.</p>\r\n\r\n<p>Join us on 26th September at Sunbird Livingstonia Beach &amp; Water Front, Salima.</p>', '', '1790278239_Session 4.jpeg', 'Admin', '2026-09-24', 'Conference', '', 'published', '2026-09-24 19:30:39', 0, '', 0),
(35, 'PSA 4th Biennial Conference Session 6 - Citizenship, Civil Society and Public Opinion', 'psa-4th-biennial-conference-session-6---citizenship-civil-society-and-public-opinion', '<p>Session 6 -&nbsp;<em>Citizenship, Civil Society and Public Opinion,&nbsp;</em>&nbsp;is chaired by Prof. Mustafa Hussein (Professor of Public Administration, University of Malawi),</p>\r\n\r\n<p>featuring</p>\r\n\r\n<p>1. Dr. Llyod George Banda,<br />\r\n2.&nbsp;Tapiwa Ngwembe and Dr. Felix Lombe,<br />\r\n3.&nbsp;Nadia Notiyhella Nathoo and<br />\r\n4.&nbsp;Kondwani Gondwe.</p>\r\n\r\n<p>Join us on 26th September at Sunbird Livingstonia Beach &amp; Water Front, Salima.</p>', '', '1790278374_Session 6.jpeg', '', '2026-09-24', '', '', 'published', '2026-09-24 19:32:54', 0, '', 0),
(36, 'PSA Elects New Executive Council for 2026–2028', 'psa-elects-new-executive-council-for-2026-2028', '<p>The Malawi Political Science Association (PSA) is pleased to announce the election of its new Executive Council, which will serve from October 2026 to September 2028. The election took place during the Elective Annual General Meeting (AGM) on Day Two of the PSA 4th Biennial Conference, held at Sunbird Livingstonia Beach and Waterfront.</p>\r\n\r\n<p>The newly elected Executive Council is:</p>\r\n\r\n<ul>\r\n	<li><strong>President:</strong> Professor&nbsp;Michael Chasukwa, Professor of Political Science, University of Malawi</li>\r\n	<li><strong>Vice President:</strong> Annie Sainala Kalebe, Lecturer in Political Science, Catholic University of Malawi.&nbsp;</li>\r\n	<li><strong>Secretary General:</strong> Mavuto Bamusi, Technical Advisor for Civil Society Strengthening, GIZ</li>\r\n	<li><strong>Treasurer General:</strong> Dr. Clemence Alfazema, Palladium</li>\r\n	<li><strong>Publicity Secretary:</strong> Dr. George Chaima, Political Analyst and Executive Director, New Restoration Plan</li>\r\n	<li><strong>Executive Members:</strong>\r\n	<ul>\r\n		<li>Associate&nbsp;Prof. Nandini Patel, Institute for Policy Interaction (IPI)</li>\r\n		<li>Beauty Msiska Phiri, Lecturer in Political Science, Catholic University of Malawi</li>\r\n		<li>Dr. Chrispine Mphande, Lecturer in History and Development Studies, Mzuzu University</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<p>On behalf of the entire membership, the PSA congratulates the new Executive Council on this mandate. We thank the outgoing Executive Council for its service and leadership, and we look forward to continued growth for the Association under the new leadership.</p>\r\n\r\n<p><em>Visit <a href=\"http://www.malawipsa.org\">www.malawipsa.org</a> | <a href=\"mailto:admin@malawipsa.org\">admin@malawipsa.org</a></em></p>', '', '1790619915_Congratutory message.jpeg', 'Admin', '2026-09-28', 'Updates', '', 'published', '2026-09-28 18:25:15', 0, '', 0);
